parameters.functionScript:
/*
 * ONE BUNDLE, TWO HALVES, TWO CONSUMERS (TASK-L161 §0b).
 *
 *   the kit's 80   — GENERATED from library/modules/dbt-lesson/src/kit.js
 *   the graph's 19 — AUTHORED in the node beside this one
 *
 * They are merged here and nowhere else. The merge REFUSES to pick a winner:
 * a key present in both halves is the drift this sprint exists to prevent, so
 * it is reported to the console, which render_report surfaces as a console
 * error and a template therefore cannot ship with one.
 *
 * `copy` goes to the kit as an OBJECT. The `json*` outputs go to App's
 * `Language Bundle` nodes as STRINGS, because `Language Bundle.Bundle` parses
 * JSON text and loads it under exactly ONE namespace (measured, L161 §0).
 *
 * THREE HALVES NOW, AND THE THIRD IS THE LOCALE (TASK-L162 §2). English is the
 * BASE and a locale is an OVERLAY on top of it, so a key a translator has not
 * reached renders English — for the kit and for the graph's `Translation`
 * nodes alike, by ONE rule in ONE place rather than two mechanisms that happen
 * to agree. (i18next's own `fallbackLng` would give the graph half of that and
 * nothing at all to the kit, which cannot reach i18next: it exposes no global.)
 *
 * The overlay is deliberately NOT part of the collision check below. A key in
 * both English halves is drift; a key in English and in a locale is the point.
 *
 * ── AND A FOURTH LAYER, WHICH IS NOT A LANGUAGE BUT AN AUDIENCE (L163 §2) ───
 * A coach and their client read the SAME assembly (L116's one model, two
 * projections) and must not read the same sentences. That is an OVERLAY too,
 * and deliberately the same mechanism rather than a second one: 28 override
 * keys replace 65 duplicated strings, and a neutral key ('Lesson', 'Brief',
 * 'Review') keeps exactly one owner. Adding a locale is still adding one key to
 * the locale node — the coach layer composes underneath it, so a translated
 * coach string needs no third rule.
 *
 * THE COACH LAYER IS APPLIED LAST, and that is a decision rather than an
 * accident of ordering. The two orders differ only when a locale translates a
 * key the coach overrides WITHOUT also translating the coach's version of it —
 * and then locale-last would hand a coach the LEARNER's sentence, translated.
 * A locale miss falls back to English, which is wrong-language and not
 * wrong-meaning; a voice miss tells a coach "Your coach hasn't written this one
 * up yet" about their own review, which is silent and wrong. So the voice wins,
 * and `tools/check-coach-voice.py` fails the build on any that got away.
 */
function plain(x) {
  if (x === null || x === undefined) return x;
  if (Array.isArray(x)) return x.map(plain);
  if (typeof x === 'object') {
    if (typeof x.get === 'function' && x.data && typeof x.data === 'object') return plain(x.data);
    if (Array.isArray(x.items)) return plain(x.items);
    const out = {};
    for (const k of Object.keys(x)) out[k] = plain(x[k]);
    return out;
  }
  return x;
}

function first(rows) {
  const r = plain(rows) || [];
  return r[0] || {};
}

/** Every leaf path, so a collision is reported by name rather than by count. */
function leaves(o, prefix, into) {
  for (const k of Object.keys(o || {})) {
    if (k.charAt(0) === '_') continue;
    const v = o[k];
    const path = prefix ? prefix + '.' + k : k;
    if (v && typeof v === 'object') leaves(v, path, into);
    else into.push(path);
  }
  return into;
}

function deepMerge(a, b) {
  const out = {};
  for (const k of Object.keys(a || {})) out[k] = a[k];
  for (const k of Object.keys(b || {})) {
    const v = b[k];
    if (v && typeof v === 'object' && out[k] && typeof out[k] === 'object') out[k] = deepMerge(out[k], v);
    else out[k] = v;
  }
  return out;
}

const kit = first(Inputs.items);
const graph = first(Inputs.graph);

const clash = leaves(kit, '', []).filter((p) => leaves(graph, '', []).indexOf(p) !== -1);
if (clash.length) {
  console.error(
    '[Data/Strings] ' + clash.length + ' key(s) are written in BOTH halves of the string table, ' +
    'so one of them is unreachable and they are free to drift: ' + clash.join(', ') +
    '. Delete whichever copy is not the owner (TASK-L161 §0b).'
  );
}

const english = deepMerge(kit, graph);

/* WHO IS READING. No default: a page that forgot to say would otherwise get the
   learner's words with nothing reporting it, which is `service.ts:17-26`'s "one
   forgotten argument away" in a graph's clothes (L163 §3). The template's own
   convention is that a missing input arrives `undefined`, so this is what turns
   that into a named failure at the one place it is decidable. */
const audience = String(Inputs.audience || '').trim();
if (audience !== 'learner' && audience !== 'coach') {
  throw new Error(
    'Data/Strings: Audience must be "learner" or "coach", not "' + audience + '". ' +
    'Every instance says who is reading; there is no default (TASK-L163 §3).'
  );
}

/* `language` is resolved UPSTREAM, so it is only ever a locale we have content
 * for, or 'en' (TASK-L162 §1). 'en' has no overlay by construction: it is the base. */
const language = String(Inputs.language || 'en');
const locales = first(Inputs.locales);
const overlay = language === 'en' ? {} : locales[language] || {};

const localised = deepMerge(english, overlay);

/* The coach layer rides in the table under a reserved `coach` key, holding the
   same namespaces it overrides. It is lifted off before anything is handed out,
   so no consumer ever sees it as a namespace of its own and a learner's bundle
   cannot contain the coach's words at all. */
const voice = localised.coach || {};
const base = {};
for (const k of Object.keys(localised)) if (k !== 'coach') base[k] = localised[k];

/* A COACH KEY THAT DOES NOT EXIST IN THE BASE IS A TYPO THAT DOES NOTHING.
   It would merge in cleanly, render nowhere, and read in review as a string
   that is handled — so it is reported by name, the same way a clash is. */
const stray = leaves(voice, '', []).filter((p) => leaves(base, '', []).indexOf(p) === -1);
if (stray.length) {
  console.error(
    '[Data/Strings] ' + stray.length + ' coach override(s) name a key the English base does not have, ' +
    'so they replace nothing and render nowhere: ' + stray.join(', ') +
    '. Fix the spelling or delete them (TASK-L163 §2).'
  );
}

const bundle = audience === 'coach' ? deepMerge(base, voice) : base;
const ns = (n) => bundle[n] || {};

Outputs.copy = bundle;
/* The validated value, so everything downstream reads the audience from the one
   place it was decided rather than being told again and drifting (L102's rule). */
Outputs.audience = audience;
Outputs.common = ns('common');
Outputs.lesson = ns('lesson');
Outputs.timeline = ns('timeline');
Outputs.standing = ns('standing');
Outputs.productName = (bundle.common && bundle.common.productName) || '';

Outputs.jsonCommon = JSON.stringify(ns('common'));
Outputs.jsonHome = JSON.stringify(ns('home'));
Outputs.jsonCourse = JSON.stringify(ns('course'));
Outputs.jsonLesson = JSON.stringify(ns('lesson'));
Outputs.jsonPalette = JSON.stringify(ns('palette'));
Outputs.jsonPeople = JSON.stringify(ns('people'));

Outputs.loaded();

